import { readFileSync, writeFileSync } from 'node:fs';
const p = '/workspace/probe/corpus/gen_dict-key-types.mjs';
let s = readFileSync(p, 'utf8');
const NUL = '�';
if (!s.includes(NUL)) { console.log('nothing to patch'); process.exit(0); }
// the only literal NUL is inside the guard: c.includes('<NUL>')
s = s.split("'" + NUL + "'").join("'\\u0000'");
if (s.includes(NUL)) throw new Error('literal NUL still present outside quotes');
writeFileSync(p, s);
console.log('patched');
